//
//conversions


template<classU,classV>
inline
Uconv(V&img)
{
Ures;
std::stringstreambuf;

buf<<img;
buf>>res;

returnres;
}

template<classT>
inline
TconvAdaLiteral(constchar*img)
{
returnconv<T>(img);
}

template<>
longdoubleconvAdaLiteral<long double>(constchar*img);

template<>
charconvAdaLiteral<char>(constchar*img);


template<classSageValue>
inline
SageValue&mkValue(constchar*textrep)
{
static_assert(std::is_base_of<SgValueExp,SageValue>::value,
"templateargumentisnotderivedfromSgValueExp"
);

usingrose_rep_t=decltype(std::declval<SageValue>().get_value());

ASSERT_not_null(textrep);
returnmkLocatedNode<SageValue>(convAdaLiteral<rose_rep_t>(textrep),textrep);
}

template<>
SgStringVal&mkValue<SgStringVal>(constchar*textrep);

SgValueExp&
mkAdaIntegerLiteral(constchar*textrep);
